/** 时间显示。只给人看相对时间，精确到分钟没必要。 */

export function relative_time(timestamp: number, now = Date.now()): string {
  const gap = now - timestamp;
  if (!Number.isFinite(gap) || gap < 0) return '';
  const minute = 60 * 1000;
  const hour = 60 * minute;
  const day = 24 * hour;
  if (gap < minute) return '刚刚';
  if (gap < hour) return `${Math.floor(gap / minute)} 分钟前`;
  if (gap < day) return `${Math.floor(gap / hour)} 小时前`;
  if (gap < 30 * day) return `${Math.floor(gap / day)} 天前`;
  const date = new Date(timestamp);
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
}

/** 列表里的一句话摘要。 */
export function excerpt(text: string, limit = 60): string {
  const flat = text.replace(/\s+/g, ' ').trim();
  return flat.length > limit ? `${flat.slice(0, limit)}` : flat;
}
